  "adverb": {"headword": "adverb", "pos": "", "zh": "n. 副词", "en": "n. the word class that qualifies verbs or clauses\nn. a word that modifies something other than a noun"},
  "adversarial": {"headword": "adversarial", "pos": "", "zh": "a. 敌手的,对手的,对抗(性)的", "en": ""},
  "adverse": {"headword": "adverse", "pos": "", "zh": "a. 不利的, 敌对的, 相反的, 逆的\n[法] 相反的, 敌对的, 逆的", "en": "s. contrary to your interests or welfare\ns. in an opposing direction"},
  "advertise": {"headword": "advertise", "pos": "", "zh": "vt. 做广告, 通知, 公布\nvi. 做广告", "en": "v. call attention to\nv. make publicity for; try to sell (a product)"},
  "advice": {"headword": "advice", "pos": "", "zh": "n. 忠告, 劝告, 意见, 报道, 通知\n[经] 通知书, 通知, 建议", "en": "n. a proposal for an appropriate course of action"},
  "advisable": {"headword": "advisable", "pos": "", "zh": "a. 适当的, 明智的", "en": "a. worthy of being recommended or suggested; prudent or wise"},
  "advise": {"headword": "advise", "pos": "", "zh": "vt. 劝告, 给...出主意, 通知, 建议\nvi. 提意见, 商量", "en": "v. inform (somebody) of something"},
  "advisory": {"headword": "advisory", "pos": "", "zh": "a. 顾问的, 咨询的, 劝告的\n[法] 劝告的, 忠告的, 咨询的", "en": "n. an announcement that usually advises or warns the public of some threat\ns. giving advice"},
  "advocate": {"headword": "advocate", "pos": "", "zh": "n. 提倡者, 拥护者\nvt. 主张, 提倡", "en": "n. a person who pleads for a cause or propounds an idea\nn. a lawyer who pleads cases in court"},
