  "cafe": {"headword": "cafe", "pos": "", "zh": "n. 咖啡馆, 酒店", "en": "n. a small restaurant where drinks and snacks are sold"},
  "cafeteria": {"headword": "cafeteria", "pos": "", "zh": "n. 自助餐厅\n[经] 自助餐厅", "en": "n. a restaurant where you serve yourself and pay a cashier"},
