  "confess": {"headword": "confess", "pos": "", "zh": "v. 承认, 坦白, 忏悔, 供认", "en": "v. confess to a punishable or reprehensible deed, usually under pressure\nv. confess to God in the presence of a priest, as in the Catholic faith"},
  "confidant": {"headword": "confidant", "phonetic": ".kɒnfi'dænt", "pos": "", "zh": "n. 心腹朋友, 知己", "en": "n. someone to whom private matters are confided"},
  "confidence": {"headword": "confidence", "pos": "", "zh": "n. 信心\n[电] 可靠", "en": "n. a feeling of trust (in someone or something)\nn. a state of confident hopefulness that events will be favorable\nn. a trustful relationship\nn. a secret that is confided or entrusted to another"},
  "confident": {"headword": "confident", "pos": "", "zh": "a. 有信心的, 有把握的", "en": "a. having or marked by confidence or assurance\ns. not liable to error in judgment or action"},
