  "congratulate": {"headword": "congratulate", "pos": "", "zh": "vt. 祝贺, 庆贺", "en": "v. express congratulations"},
  "congratulation": {"headword": "congratulation", "pos": "", "zh": "n. 祝贺, 恭喜", "en": "n. the act of acknowledging that someone has an occasion for celebration\nn. (usually plural) an expression of pleasure at the success or good fortune of another"},
