  "correspond": {"headword": "correspond", "phonetic": ".kɒri'spɒnd", "pos": "", "zh": "vi. 符合, 通信, 相当\n[法] 符合, 一致, 相当", "en": "v. exchange messages"},
  "correspondence": {"headword": "correspondence", "pos": "", "zh": "n. 相符, 通信, 信件\n[医] 对应, 相对", "en": "n. communication by the exchange of letters"},
  "correspondent": {"headword": "correspondent", "pos": "", "zh": "n. 通讯记者, 通信者\n[经] 客户, 代理商行, 代理银行", "en": "n. someone who communicates by means of letters\nn. a journalist employed to provide news stories for newspapers or broadcast media"},
