  "countryside": {"headword": "countryside", "phonetic": "'kʌntrisaid", "pos": "", "zh": "n. 乡下地方, 乡下居民", "en": "n. rural regions"},
  "county": {"headword": "county", "phonetic": "'kaunti", "pos": "", "zh": "n. 县, 郡", "en": "n. (United Kingdom) a region created by territorial division for the purpose of local government\nn. (United States) the largest administrative district within a state"},
  "couple": {"headword": "couple", "phonetic": "'kʌpl", "pos": "", "zh": "n. 对, 夫妇, 数个\nvt. 使成双, 连接, 使成婚, 把...联系起来\nvi. 结合, 成婚", "en": "n. a pair who associate with one another\nn. a pair of people who live together\nn. a small indefinite number\nn. two items of the same kind"},
  "coupon": {"headword": "coupon", "pos": "", "zh": "n. 息票, 赠券\n[经] 息票, 利息单, 联票", "en": "n. a negotiable certificate that can be detached and redeemed as needed\nn. a test sample of some substance"},
  "courage": {"headword": "courage", "phonetic": "'kʌridʒ", "pos": "", "zh": "n. 勇气, 胆量", "en": "n. a quality of spirit that enables you to face danger or pain without showing fear"},
  "courageous": {"headword": "courageous", "pos": "", "zh": "a. 勇敢的, 大胆的, 有胆量的", "en": "a possessing or displaying courage; able to face and deal with danger or fear without flinching"},
  "course": {"headword": "course", "pos": "", "zh": "n. 课程, 路线, 过程, 一道菜, 道路\nv. 追, (使)跑", "en": "n. education imparted in a series of lessons or meetings\nn. a connected series of events or actions or developments\nn. general line of orientation\nn. a mode of action"},
