  "daily": {"headword": "daily", "phonetic": "'deili", "pos": "", "zh": "a. 每日的, 日常的\nadv. 每日地, 日常地\nn. 日报", "en": "n. a newspaper that is published every day\ns. of or belonging to or occurring every day\nr. every day; without missing a day"},
  "dairy": {"headword": "dairy", "pos": "", "zh": "n. 牛奶公司, 乳品店, 乳牛场", "en": "n. a farm where dairy products are produced"},
