  "dentist": {"headword": "dentist", "phonetic": "'dentist", "pos": "", "zh": "n. 牙科医生\n[医] 牙医师", "en": "n. a person qualified to practice dentistry"},
  "deny": {"headword": "deny", "phonetic": "di'nai", "pos": "", "zh": "v. 否认, 拒绝", "en": "v. declare untrue; contradict\nv. refuse to accept or believe\nv. refuse to grant, as of a petition or request\nv. refuse to let have"},
