  "doctoral": {"headword": "doctoral", "pos": "", "zh": "a. 博士的", "en": "a. of or relating to a doctor or doctorate"},
  "doctorate": {"headword": "doctorate", "pos": "", "zh": "n. 博士头衔", "en": "n one of the highest earned academic degrees conferred by a university"},
  "doctrine": {"headword": "doctrine", "phonetic": "'dɒktrin", "pos": "", "zh": "n. 教条, 学说\n[医] 学说", "en": "n. a belief (or system of beliefs) accepted as authoritative by some group or school"},
  "document": {"headword": "document", "pos": "", "zh": "n. 文件, 公文, 文档\nvt. 证明, 为...引证\n[计] 文档", "en": "n. writing that provides information (especially information of an official nature)\nn. anything serving as a representation of a person's thinking by means of symbolic marks\nn. a written account of ownership or obligation\nv. record in detail"},
  "documentary": {"headword": "documentary", "pos": "", "zh": "n. 记录片\na. 文件的", "en": "n. a film or TV program presenting the facts about a person or event\na. relating to or consisting of or derived from documents"},
