  "doorway": {"headword": "doorway", "pos": "", "zh": "n. 门口, 途径", "en": "n. the entrance (the space in a wall) through which you enter or leave a room or building; the space that a door can close"},
  "dorm": {"headword": "dorm", "pos": "", "zh": "n. 宿舍", "en": "n a college or university building containing living quarters for students"},
  "dormant": {"headword": "dormant", "pos": "", "zh": "a. 睡眠状态的, 静止的\n[医] 休眠的, 不活动的, 休止的", "en": "s. in a condition of biological rest or suspended animation\na. (of e.g. volcanos) not erupting and not extinct\ns. lying with head on paws as if sleeping"},
