  "doubtless": {"headword": "doubtless", "phonetic": "'dautlis", "pos": "", "zh": "a. 无疑的, 确定的\nadv. 无疑地, 确定地", "en": "r without doubt; certainly"},
  "dove": {"headword": "dove", "phonetic": "dʌv", "pos": "", "zh": "n. 鸽子\ndive的过去式", "en": "n. any of numerous small pigeons\nn. someone who prefers negotiations to armed conflict in the conduct of foreign relations\nn. an emblem of peace"},
