  "download": {"headword": "download", "pos": "", "zh": "[计] 卸载, 下栽", "en": "v. transfer a file or program from a central computer to a smaller computer or to a computer at a remote location"},
  "downside": {"headword": "downside", "phonetic": "'daunsaid", "pos": "", "zh": "n. 底侧；下降趋势", "en": "n. a negative aspect of something that is generally positive"},
  "downstairs": {"headword": "downstairs", "pos": "", "zh": "n. 楼下\na. 楼下的\nadv. 在楼下", "en": "a. on or of lower floors of a building\nr. on a floor below"},
