  "entity": {"headword": "entity", "phonetic": "'entiti", "pos": "", "zh": "n. 实体, 实存物, 存在\n[计] 实体", "en": "n. that which is perceived or known or inferred to have its own distinct existence (living or nonliving)"},
  "entourage": {"headword": "entourage", "pos": "", "zh": "n. 全体随行人员, 陪同人员", "en": "n the group following and attending to some important person"},
