  "june": {"headword": "june", "pos": "", "zh": "n. 六月", "en": "n. the month following May and preceding July"},
  "jungle": {"headword": "jungle", "phonetic": "'dʒʌŋgl", "pos": "", "zh": "n. 丛林, 杂乱的一堆, 弱肉强食的地方", "en": "n. a location marked by an intense competition and struggle for survival\nn. an impenetrable equatorial forest"},
