  "lately": {"headword": "lately", "phonetic": "'leitli", "pos": "", "zh": "adv. 近来, 最近", "en": "r in the recent past"},
  "latent": {"headword": "latent", "phonetic": "'leitnt", "pos": "", "zh": "a. 潜伏性的, 隐藏的\nn. 隐约指纹", "en": "s. potentially existing but not presently evident or realized\ns. (pathology) not presently active"},
  "later": {"headword": "later", "pos": "", "zh": "adv. 以后, 随后", "en": "s. coming at a subsequent time or stage\nr. comparative of the adverb `late'"},
  "lateral": {"headword": "lateral", "pos": "", "zh": "n. 侧部, 支线, 边音\na. 侧面的, 旁边的", "en": "s. situated at or extending to the side\ns. lying away from the median and sagittal plane of a body"},
