  "layman": {"headword": "layman", "pos": "", "zh": "n. 俗人, 门外汉, 凡人\n[医] 外行, 业外人", "en": "n. someone who is not a clergyman or a professional person"},
  "layoff": {"headword": "layoff", "phonetic": "'leiɒf", "pos": "", "zh": "n. 临时解雇, 操作停止, 活动停止期间", "en": "n. the act of laying off an employee or a work force"},
  "layout": {"headword": "layout", "phonetic": "'leiaut", "pos": "", "zh": "n. 布局, 陈列, 规划图, 页面布局, 版面编排\n[计] 页面布局, 版面", "en": "n. a plan or design of something that is laid out\nn. the act of laying out (as by making plans for something)"},
  "lazy": {"headword": "lazy", "phonetic": "'leizi", "pos": "", "zh": "a. 懒惰的, 怠惰的, 缓慢的\nvi. 懒散", "en": "s. moving slowly and gently"},
