  "lunar": {"headword": "lunar", "pos": "", "zh": "a. 阴历的, 月的, 微亮的(指光)\n[医] 月的, 银的", "en": "a. of or relating to or associated with the moon"},
  "lunch": {"headword": "lunch", "phonetic": "lʌntʃ", "pos": "", "zh": "n. 午餐", "en": "n. a midday meal\nv. take the midday meal\nv. provide a midday meal for"},
