  "mankind": {"headword": "mankind", "phonetic": "mæn'kaind", "pos": "", "zh": "n. 人类, 男性", "en": "n all of the living human inhabitants of the earth"},
  "manner": {"headword": "manner", "pos": "", "zh": "n. 样子, 礼貌, 风格\n[法] 方式, 方法, 样式", "en": "n. how something is done or how it happens\nn. a way of acting or behaving\nn. a kind"},
