  "powerful": {"headword": "powerful", "pos": "", "zh": "a. 有力的, 有权力的, 强大的\n[机] 强力的", "en": "a. having great power or force or potency or effect"},
  "powerfully": {"headword": "powerfully", "pos": "", "zh": "adv. 强有力, 强大, 效力大, 有权威, 权力大, 有影响, 很多, 相当, 非常", "en": "r. in a powerful manner"},
  "powerless": {"headword": "powerless", "pos": "", "zh": "a. 无力的, 无权的, 无效能的", "en": "a. lacking power"},
  "practical": {"headword": "practical", "phonetic": "'præktikl", "pos": "", "zh": "a. 实际的, 现实的, 实用性的\n[法] 事实上的, 实际上的, 接近...的", "en": "a. concerned with actual use or practice\ns. having or put to a practical purpose or use"},
  "practicality": {"headword": "practicality", "phonetic": ".prækti'kæliti", "pos": "", "zh": "n. 实际性, 实用性, 实际事物", "en": "n. concerned with actual use rather than theoretical possibilities"},
  "practically": {"headword": "practically", "phonetic": "'præktikli", "pos": "", "zh": "adv. 几乎, 差不多, 事实上", "en": "r. almost; nearly\nr. in a practical manner"},
  "practice": {"headword": "practice", "phonetic": "'præktis", "pos": "", "zh": "n. 实践, 练习, 实行, 惯例, 习惯, 开业\nv. 实践, 实行, 练习, 实习, 业务", "en": "n. a customary way of operation or behavior\nn. translating an idea into action\nn. the exercise of a profession\nn. knowledge of how something is usually done"},
  "practise": {"headword": "practise", "phonetic": "'præktis", "pos": "", "zh": "v. 实践, 实行, 练习, 实习, 从事(职业)", "en": "v engage in a rehearsal (of)\nv carry out or practice; as of jobs and professions\nv learn by repetition"},
  "practitioner": {"headword": "practitioner", "pos": "", "zh": "n. 从业者, 开业者\n[医] 行医者, 医师", "en": "n. someone who practices a learned profession"},
  "prairie": {"headword": "prairie", "pos": "", "zh": "n. 大草原, 草甸", "en": "n. a treeless grassy plain"},
  "praise": {"headword": "praise", "phonetic": "preiz", "pos": "", "zh": "n. 赞美, 称赞, 崇拜\nvt. 称赞, 赞美\nvi. 赞扬, 表扬", "en": "n. an expression of approval and commendation\nn. offering words of homage as an act of worship\nv. express approval of"},
  "pray": {"headword": "pray", "phonetic": "prei", "pos": "", "zh": "v. 祈祷, 恳求, 请", "en": "v. address a deity, a prophet, a saint or an object of worship; say a prayer"},
  "prayer": {"headword": "prayer", "pos": "", "zh": "n. 祈祷, 恳求, 祷辞, 祈祷者", "en": "n. the act of communicating with a deity (especially as a petition or in adoration or contrition or thanksgiving)\nn. reverent petition to a deity\nn. a fixed text used in praying\nn. someone who prays to God"},
  "preach": {"headword": "preach", "pos": "", "zh": "v. 传道, 讲道, 说教, 宣讲, 鼓吹\nn. 说教, 布道", "en": "v. deliver a sermon\nv. speak, plead, or argue in favor of"},
  "precaution": {"headword": "precaution", "pos": "", "zh": "n. 预防, 留心, 警戒\nvt. 预先警告", "en": "n. a precautionary measure warding off impending danger or damage or injury etc.\nn. the trait of practicing caution in advance"},
