  "saint": {"headword": "saint", "phonetic": "seint", "pos": "", "zh": "n. 圣徒, 圣人\na. 神圣的\n[计] 自动积分程序符号", "en": "n. a person who has died and has been declared a saint by canonization\nn. person of exceptional holiness"},
  "sake": {"headword": "sake", "phonetic": "seik", "pos": "", "zh": "n. 目的, 缘故, 理由", "en": "n. a reason for wanting something done\nn. Japanese alcoholic beverage made from fermented rice; usually served hot\nn. the purpose of achieving or obtaining"},
  "salad": {"headword": "salad", "pos": "", "zh": "n. 色拉", "en": "n. food mixtures either arranged on a plate or tossed and served with a moist dressing; usually consisting of or including greens"},
