  "superb": {"headword": "superb", "pos": "", "zh": "a. 极度的, 华丽的, 极好的", "en": "s. surpassingly good"},
  "superficial": {"headword": "superficial", "pos": "", "zh": "n. 表面, 外表\na. 表面的, 肤浅的, 面积的", "en": "a. concerned with or comprehending only what is apparent or obvious; not deep or penetrating emotionally or intellectually\na. of, affecting, or being on or near the surface\ns. of little substance or significance"},
  "superfluous": {"headword": "superfluous", "pos": "", "zh": "a. 多余的, 过剩的", "en": "s serving no useful purpose; having no excuse for being\ns more than is needed, desired, or required"},
