  "unjust": {"headword": "unjust", "phonetic": ".ʌn'dʒʌst", "pos": "", "zh": "a. 不公平的\n[法] 不公正的人; 不公正的, 不公平的, 不合理的", "en": "a. violating principles of justice"},
  "unknowable": {"headword": "unknowable", "pos": "", "zh": "a. 不能知道的, 不可知的", "en": "a. not knowable"},
