  "unnatural": {"headword": "unnatural", "pos": "", "zh": "a. 不自然的, 反常的, 不近人情的\n[法] 不自然的, 违背人道, 邪恶的", "en": "a. not in accordance with or determined by nature; contrary to nature"},
  "unnecessarily": {"headword": "unnecessarily", "pos": "", "zh": "adv. 不必要地, 多余地", "en": "r. in an unnecessary manner\nr. without any necessity"},
