  "unpredictability": {"headword": "unpredictability", "phonetic": "ˌʌnprɪˌdɪktə'bɪlətɪ", "pos": "", "zh": "不可预测性, 不可预知性", "en": "n. lacking predictability"},
  "unpredictable": {"headword": "unpredictable", "pos": "", "zh": "a. 不可预知的", "en": "a. not capable of being foretold\ns. unknown in advance"},
  "unpretentious": {"headword": "unpretentious", "pos": "", "zh": "a. 不铺张的, 不炫耀的, 不装模作样的, 不招摇的, 谦逊的, 质朴的", "en": "a. lacking pretension or affectation"},
